#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=5

banner "Meeting Ledger local speaker diarization on Windows"

stage "Preflight"
say "This provisions a local, offline pyannote Community-1 pilot. It keeps this app loopback-only and produces anonymous labels only."
case "$(uname -s)" in
  MINGW*|MSYS*) ;;
  *)
    warn "This shell is not Git Bash (from PowerShell, plain 'bash' usually opens WSL)."
    say "Rerun with: & \"C:\\Program Files\\Git\\bin\\bash.exe\" scripts/setup-windows-diarization.sh"
    exit 1
    ;;
esac
step "Run this from Git Bash in the repository. Install Python 3.10 or 3.11, Git for Windows, and Git LFS first. FFmpeg is not needed: the worker decodes the server's PCM WAV itself."
step "Choose a protected directory writable by the Meeting Ledger service account for the Python environment, model, temporary files, and provenance inventory."
if command -v git >/dev/null 2>&1 && command -v git-lfs >/dev/null 2>&1; then
  note "Found git and git-lfs on PATH."
else
  warn "git and git-lfs must be installed before model acquisition."
fi
pause "Complete the preflight and press Enter"

stage "Accept the gated model conditions"
say "Community-1 is CC-BY-4.0 and gated. Hugging Face grants access to individual user accounts after they share contact information with the model authors."
open_url "https://huggingface.co/pyannote/speaker-diarization-community-1"
step "Sign in, review the conditions, and select the option to accept/share the requested contact information."
step "Wait for access approval if the page says your request is pending."
pause "The account has access to Community-1; press Enter"

stage "Choose the local paths and install the runtime"
say "The base Python is used only to create an isolated runtime. The server will use the virtual-environment Python path instead."
ask BASE_PYTHON "Paste the full path to Python 3.10 or 3.11 (for example C:/Python311/python.exe):"
ask MODEL_ROOT "Paste the protected parent directory for local diarization assets:"
# Accept pasted Windows paths: drop surrounding quotes/whitespace and use forward slashes.
normalize_path() {
  local p="$1"
  p="${p#"${p%%[![:space:]]*}"}"; p="${p%"${p##*[![:space:]]}"}"
  p="${p#\"}"; p="${p%\"}"; p="${p#\'}"; p="${p%\'}"
  printf '%s' "${p//\\//}"
}
BASE_PYTHON=$(normalize_path "$BASE_PYTHON")
MODEL_ROOT=$(normalize_path "$MODEL_ROOT")
if [[ -z "$BASE_PYTHON" || -z "$MODEL_ROOT" ]]; then
  warn "Both paths are required. Stop now and rerun when they are available."
  exit 1
fi
"$BASE_PYTHON" -c 'import sys; assert sys.version_info >= (3, 10), "Python 3.10+ is required"'
VENV_DIR="$MODEL_ROOT/runtime"
MODEL_DIR="$MODEL_ROOT/speaker-diarization-community-1"
TEMP_DIR="$MODEL_ROOT/tmp"
PYTHON_FOR_ENV="$VENV_DIR/Scripts/python.exe"
mkdir -p "$MODEL_ROOT" "$TEMP_DIR"
if [[ ! -x "$PYTHON_FOR_ENV" ]]; then
  "$BASE_PYTHON" -m venv "$VENV_DIR"
fi
"$PYTHON_FOR_ENV" -m pip install --upgrade pip
"$PYTHON_FOR_ENV" -m pip install "pyannote.audio==4.0.7"

stage "Acquire the approved model once"
say "Git will prompt for a Hugging Face username and password. Use your account name and a fine-grained token with the access required by the model card."
say "The command disables Git credential helpers for this clone. Do not paste the token into .env, source code, or this chat."
open_url "https://huggingface.co/settings/tokens"
step "Create the token only after reviewing the model card's current access requirement. Keep it available for the Git password prompt."
if [[ -d "$MODEL_DIR/.git" ]]; then
  note "A model Git repository already exists at the selected path; it will not be changed."
else
  git lfs install
  git -c credential.helper= clone https://hf.co/pyannote/speaker-diarization-community-1 "$MODEL_DIR"
fi

stage "Prove offline execution and configure the server"
say "The validation creates a one-second silent WAV and a bounded JSON output in the protected temporary directory, then removes both."
SAMPLE_WAV="$TEMP_DIR/provisioning-silence.wav"
SAMPLE_OUTPUT="$TEMP_DIR/provisioning-turns.json"
trap 'rm -f "$SAMPLE_WAV" "$SAMPLE_OUTPUT"' EXIT
"$PYTHON_FOR_ENV" - "$SAMPLE_WAV" <<'PY'
import sys
import wave
with wave.open(sys.argv[1], "wb") as output:
    output.setnchannels(1)
    output.setsampwidth(2)
    output.setframerate(16000)
    output.writeframes(b"\x00\x00" * 16000)
PY
HF_HUB_OFFLINE=1 TRANSFORMERS_OFFLINE=1 HF_DATASETS_OFFLINE=1 PYANNOTE_METRICS_ENABLED=0 \
  "$PYTHON_FOR_ENV" server/diarize_worker.py --model "$MODEL_DIR" --input "$SAMPLE_WAV" --output "$SAMPLE_OUTPUT"
"$PYTHON_FOR_ENV" - "$SAMPLE_OUTPUT" <<'PY'
import json
import sys
value = json.load(open(sys.argv[1], encoding="utf-8"))
assert value.get("version") == 1 and isinstance(value.get("turns"), list)
PY
{
  echo "model_repository=pyannote/speaker-diarization-community-1"
  echo "model_revision=$(git -C "$MODEL_DIR" rev-parse HEAD)"
  echo "acquired_at_utc=$(date -u +%Y-%m-%dT%H:%M:%SZ)"
  "$PYTHON_FOR_ENV" -m pip freeze
  find "$MODEL_DIR" -type f -exec sha256sum {} \;
} > "$MODEL_ROOT/community-1-inventory.txt"
write_env DIARIZATION_PYTHON "$PYTHON_FOR_ENV"
write_env DIARIZATION_MODEL_DIR "$MODEL_DIR"
write_env MEETING_DIARIZATION_TEMP_DIR "$TEMP_DIR"
step "Before enabling real recordings, create a Windows outbound firewall block for this virtual-environment Python executable and retain the inventory file with the license notice."
step "Restart the loopback-only preview after this wizard. The Hugging Face token is not saved and is not needed at runtime."

finish
: <<'LEGACY_TEMPLATE_EXAMPLE'

banner "Stripe setup"

# ── Example stage: replace with your real steps ───────────────────────────
stage "Stripe: API keys"
say "We'll grab your Stripe test keys and store them for local dev + CI."
open_url "https://dashboard.stripe.com/test/apikeys"
step "On the API keys page, copy the Publishable key (starts pk_test_)."
ask STRIPE_PUBLISHABLE_KEY "Paste the publishable key:"
step "Click 'Reveal test key' on the Secret key row, then copy it."
ask_secret STRIPE_SECRET_KEY "Paste the secret key:"
write_env STRIPE_PUBLISHABLE_KEY "$STRIPE_PUBLISHABLE_KEY"
write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
set_secret STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"   # CI needs this one
# ──────────────────────────────────────────────────────────────────────────

finish
LEGACY_TEMPLATE_EXAMPLE
